<?php

/*
 * Test that deleting an object that has no ID yet, because its ID is generated by the database and it hasn't been
 * saved, runs no query rather than failing, but still marks the object as deleted.
 */

use Programster\PgsqlObjects\Exceptions\ExceptionObjectDeleted;

class TestDeleteUnsavedObject
{
    public function __construct()
    {
        $db = ConnectionHandler::getDb();
        $db->query("TRUNCATE {$db->escapeIdentifier("ticket")} RESTART IDENTITY");
        TicketTable::getInstance()->emptyCache();
    }


    public function run() : void
    {
        $table = TicketTable::getInstance();
        $existing = $table->insert(['title' => 'existing']);
        $unsaved = TicketRecord::createNewFromArray(['title' => 'unsaved']);

        if ($unsaved->getId() !== null)
        {
            throw new \Exception("Expected the unsaved ticket to have no ID, as the database generates them.");
        }

        $unsaved->delete();
        $remaining = $table->loadAll();

        if (count($remaining) !== 1 || $remaining[0]->getId() !== $existing->getId())
        {
            throw new \Exception("Deleting an unsaved object changed the rows in the table.");
        }

        // it is still marked as deleted, so it can't be saved, but a clone of it can be.
        $threw = false;

        try
        {
            $unsaved->save();
        }
        catch (ExceptionObjectDeleted)
        {
            $threw = true;
        }

        if ($threw === false)
        {
            throw new \Exception("An unsaved object that was deleted could still be saved.");
        }

        $clone = clone $unsaved;
        $clone->save();

        if ($clone->getId() === null || count($table->loadAll()) !== 2)
        {
            throw new \Exception("The clone of a deleted unsaved object could not be saved.");
        }
    }
}
